solution.grade_school.zig:
const std = @import("std");

pub const Student = struct { name: []const u8, grade: u32 };
pub const School = struct {
    students: std.array_list.Managed(Student),
    additions: std.array_list.Managed(bool),
    pub fn init(allocator: std.mem.Allocator) School {
        return .{ .students = std.array_list.Managed(Student).init(allocator), .additions = std.array_list.Managed(bool).init(allocator) };
    }
    pub fn deinit(self: *School) void {
        for (self.students.items) |s| self.students.allocator.free(s.name);
        self.students.deinit();
        self.additions.deinit();
    }
    pub fn addStudent(self: *School, name: []const u8, grade_number: u32) !void {
        for (self.students.items) |student| if (std.mem.eql(u8, student.name, name)) {
            try self.additions.append(false);
            return;
        };
        const copy = try self.students.allocator.dupe(u8, name);
        errdefer self.students.allocator.free(copy);
        try self.students.ensureUnusedCapacity(1);
        try self.additions.append(true);
        self.students.appendAssumeCapacity(.{ .name = copy, .grade = grade_number });
    }
    /// Returns and clears the record of attempted additions. Caller owns the slice.
    pub fn added(self: *School) ![]bool {
        return self.additions.toOwnedSlice();
    }
    fn less(_: void, left: Student, right: Student) bool {
        return left.grade < right.grade or (left.grade == right.grade and std.mem.order(u8, left.name, right.name) == .lt);
    }
    /// Caller owns the outer slice; names stay owned by School.
    pub fn roster(self: School, allocator: std.mem.Allocator) ![][]const u8 {
        const sorted = try allocator.dupe(Student, self.students.items);
        defer allocator.free(sorted);
        std.mem.sort(Student, sorted, {}, less);
        const result = try allocator.alloc([]const u8, sorted.len);
        for (sorted, 0..) |s, i| result[i] = s.name;
        return result;
    }
    pub fn grade(self: School, allocator: std.mem.Allocator, grade_number: u32) ![][]const u8 {
        const sorted = try allocator.dupe(Student, self.students.items);
        defer allocator.free(sorted);
        std.mem.sort(Student, sorted, {}, less);
        var result = std.array_list.Managed([]const u8).init(allocator);
        errdefer result.deinit();
        for (sorted) |s| if (s.grade == grade_number) {
            try result.append(s.name);
        };
        return result.toOwnedSlice();
    }
};

tests.test_grade_school.zig:
const std = @import("std");
const t = std.testing;
const a = t.allocator;
const m = @import("grade_school.zig");

test "roster sorting, duplicate students across grades and addition history" {
    var school = m.School.init(a);
    defer school.deinit();
    const initial = try school.roster(a);
    defer a.free(initial);
    try t.expectEqual(@as(usize, 0), initial.len);
    try school.addStudent("Zoe", 3);
    try school.addStudent("Blair", 2);
    try school.addStudent("Amy", 2);
    try school.addStudent("Amy", 3);
    const added = try school.added();
    defer a.free(added);
    try t.expectEqualSlices(bool, &.{ true, true, true, false }, added);
    const reset = try school.added();
    defer a.free(reset);
    try t.expectEqual(@as(usize, 0), reset.len);
    const roster = try school.roster(a);
    defer a.free(roster);
    try t.expectEqual(@as(usize, 3), roster.len);
    try t.expectEqualStrings("Amy", roster[0]);
    try t.expectEqualStrings("Blair", roster[1]);
    try t.expectEqualStrings("Zoe", roster[2]);
    const second = try school.grade(a, 2);
    defer a.free(second);
    try t.expectEqual(@as(usize, 2), second.len);
    try t.expectEqualStrings("Amy", second[0]);
    const unknown = try school.grade(a, 9);
    defer a.free(unknown);
    try t.expectEqual(@as(usize, 0), unknown.len);
}
